import{_ as t,C as p,o as l,c as o,a3 as i,E as r,w as h,j as s,a as n}from"./chunks/framework.D_bNC8Ic.js";const w=JSON.parse('{"title":"Set up your agent","description":"","frontmatter":{},"headers":[],"relativePath":"ai/setup.md","filePath":"ai/setup.md"}'),c={name:"ai/setup.md"};function d(m,a,u,f,k,g){const e=p("ManualRelated");return l(),o("div",null,[a[1]||(a[1]=i('<h1 id="set-up-your-agent" tabindex="-1">Set up your agent <a class="header-anchor" href="#set-up-your-agent" aria-label="Permalink to &quot;Set up your agent&quot;">​</a></h1><p>Paste one block into your agent. It installs the s32 CLI, checks it, and saves the s32-cli skill with the rules to follow. You only paste: the words in the block are for the agent. Numbers match the panel: knob 01 is <code>1</code>, rack 1 is <code>1</code>.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Close the <a href="https://editor.shik.tech" target="_blank" rel="noreferrer">web editor</a>. The S32 talks to one app at a time. That is all you do before you paste. If you do not have the s32 CLI yet, the block below installs it for you, or use the <a href="./../developers/getting-started">one-line install</a>.</p><h2 id="starter-prompt" tabindex="-1">Paste this into your agent <a class="header-anchor" href="#starter-prompt" aria-label="Permalink to &quot;Paste this into your agent {#starter-prompt}&quot;">​</a></h2><p>The block works for every agent. Use the Copy button in its corner, then paste it at the start of a session. It holds the setup steps and the s32-cli skill. The agent asks before it installs anything.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Set up the s32 CLI so you can work with my S32 MIDI controller. The s32 CLI talks to the S32 over USB. Do the steps in order and tell me how each one went.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>1. Install the s32 CLI. Show me the command and wait for my yes before you run it.</span></span>\n<span class="line"><span>   macOS or Linux: curl --proto &#39;=https&#39; --tlsv1.2 -fsSL https://github.com/Shik-Tech/S32-CLI/releases/latest/download/install.sh | sh</span></span>\n<span class="line"><span>   Windows (PowerShell): irm https://github.com/Shik-Tech/S32-CLI/releases/latest/download/install.ps1 | iex</span></span>\n<span class="line"><span>   Never run sudo yourself. On Linux the installer may stop and name a command for the USB library, or print the commands that add the S32 USB rule. Both start with sudo. Show them to me and wait until I say I ran them. After the USB library, run the installer again.</span></span>\n<span class="line"><span>   If the s32 command is not found afterwards, open a new terminal, or add the folder the installer names to PATH.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>2. Check it without the S32: run `s32 --version`, then `s32 --loopback hello`. --loopback uses a simulator. It starts fresh on every run, and its ids, names and ranges are not my S32&#39;s.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>3. Check it with the S32. I close the S32 web editor first: the S32 talks to one app at a time. Run `s32 hello`. If it fails, stop and show me the error.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>4. Save the skill: the lines after the line &quot;=== s32-cli skill (SKILL.md) ===&quot; are the text of the s32-cli skill, with the rules to follow. Leave that marker line itself out. If you support Agent Skills, save those lines as a new skill named s32-cli (they are the skill&#39;s SKILL.md). Otherwise save the same lines to the rules file you read at the start of every session: AGENTS.md, CLAUDE.md or your tool&#39;s own rules file. Tell me where you saved it.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>5. Check the setup: run `s32 --version` and `s32 active`, then tell me the s32 CLI version, the name of the loaded project, and where you saved the skill. From now on, follow the skill. For anything it does not cover, read https://s32-manual.shik.tech/llms.txt.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>=== s32-cli skill (SKILL.md) ===</span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span>name: s32-cli</span></span>\n<span class="line"><span>description: Controls the S32 MIDI controller from the command line with the s32 CLI. Builds rack device chains, maps knobs, LFOs and envelopes to device parameters and MIDI, and reads and changes macros, racks, snapshots and projects safely (read, preview, ask, change, check). Use when the user mentions the S32 or the s32 CLI, or wants to change S32 racks, devices, knobs, macros, LFOs, snapshots or projects.</span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span># s32 CLI</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>The s32 CLI is the command-line tool for the S32 MIDI controller. It talks to the S32 over USB. Use it to read and change projects, racks and devices, knob macros, LFOs and snapshots.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## Before you start</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>- If the s32 CLI is not installed, ask me, then run the one-line install for my system from https://s32-manual.shik.tech/developers/getting-started. On Windows run it as `powershell -NoProfile -Command &#39;irm https://github.com/Shik-Tech/S32-CLI/releases/latest/download/install.ps1 | iex; exit $LASTEXITCODE&#39;` (single quotes, so your shell does not expand `$LASTEXITCODE` first), so a failed install returns a non-zero code.</span></span>\n<span class="line"><span>- Close the S32 web editor. The S32 talks to one app at a time.</span></span>\n<span class="line"><span>- Run `s32 hello`. Stop if it fails.</span></span>\n<span class="line"><span>- To try a command without touching the S32, add `--loopback`, for example `s32 --loopback hello`. The simulator starts fresh on every run. Its ids, names and ranges are not the S32&#39;s.</span></span>\n<span class="line"><span>- Numbers match the panel: knob 01 is `1`, macro 1 is `1`, rack 1 is `1`, and a device&#39;s place in `device list` is its number (MIDI IN is `1`). Rack and device ids (`id=` in `rack list` and `device list`) are not places. Ids are different on every S32: read them with `s32 rack list` and `s32 device list 1` just before you use one, after your last change to that rack. Never copy an id from an example or from the simulator.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## Ground rules</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>- Every setting is `key=value`. Plain numbers and names only choose what you change. Numbers match the panel: knob 01 is 1, rack 1 is 1.</span></span>\n<span class="line"><span>- Read before you change, and read again after.</span></span>\n<span class="line"><span>- Before anything that asks first, back up the active project: run `s32 active`; if it shows `dirty=1`, tell me the backup misses unsaved changes and ask whether to save first with `s32 project save --wait`. Then run `s32 pull &lt;VOLUME&gt; &lt;UID&gt; s32-backup-&lt;UID&gt;-&lt;DATE_TIME&gt;.s32p` with its volume and uid and the current date and time. If s32 pull says the file already exists, choose a new name. Never pass --force.</span></span>\n<span class="line"><span>- Preview a change with `--dry-run` and show me the preview. Pass `--yes` only after I approved that exact change.</span></span>\n<span class="line"><span>- Stop on any exit code other than 0 and show me the error.</span></span>\n<span class="line"><span>- Never run a command that s32 commands --json marks &quot;service&quot;: true, and never pass --dev. If one seems needed, stop and tell me.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## Workflow</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>1. Discover: `s32 --help` lists the commands, `s32 &lt;command&gt; --help` lists the keys of one command, `s32 commands --json` lists everything for a program.</span></span>\n<span class="line"><span>2. Read the current state: `rack list`, `device list`, `knobmap get`, `lfo cfg get`, `active`.</span></span>\n<span class="line"><span>3. Preview the change with `--dry-run` and show it to the person.</span></span>\n<span class="line"><span>4. Ask. Wait for a clear yes for that exact change.</span></span>\n<span class="line"><span>5. Change. A change prints what it did, then the new state.</span></span>\n<span class="line"><span>6. Read it back and compare with what was asked.</span></span>\n<span class="line"><span>7. Report: the commands you ran, what changed (old -&gt; new), and anything the S32 refused.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## Device parameters</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>- `s32 schema --emit-schema-json` lists every device with each parameter&#39;s id, name and range.</span></span>\n<span class="line"><span>- Names work for `rate`, `gate` and `port`. Every other parameter is its number: `device param set 1 2 87=4`.</span></span>\n<span class="line"><span>- `device add` puts a new device before MIDI OUT. If the rack already has a Clock or a MIDI OUT, do not add another.</span></span>\n<span class="line"><span>- A new MIDI IN or MIDI OUT uses PORT USB. `port=1` is MIDI1, `port=2` is MIDI2 (MIDI OUT only: a MIDI IN stores it as MIDI1), `port=3` is USB HOST.</span></span>\n<span class="line"><span>- On SYNCED, times are steps of 24 per quarter note: 96 = 1/1, 48 = 1/2, 24 = 1/4, 12 = 1/8, 6 = 1/16.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## Commands that ask first</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Each needs the person&#39;s approval and `--yes`. Preview it with `--dry-run` first.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>- `project delete` removes a stored project.</span></span>\n<span class="line"><span>- `project load` replaces the live project.</span></span>\n<span class="line"><span>- `push --activate` sends a project and plays it.</span></span>\n<span class="line"><span>- `rack clear` removes every device in a rack.</span></span>\n<span class="line"><span>- `rack duplicate` copies a rack over another.</span></span>\n<span class="line"><span>- `snapshot delete` removes a snapshot.</span></span>\n<span class="line"><span>- `globals set` changes a global setting.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## Exit codes</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>```text</span></span>\n<span class="line"><span>0 ok · 1 local file/OS error · 2 usage · 3 link</span></span>\n<span class="line"><span>4 refused by the S32 · 5 not confirmed</span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>- 0: done. Read the new state.</span></span>\n<span class="line"><span>- 1: a file on this computer. Check the path.</span></span>\n<span class="line"><span>- 2: a typo or a missing value. Nothing was sent. Read the error and `s32 &lt;command&gt; --help`.</span></span>\n<span class="line"><span>- 3: no answer from the S32, or the s32 CLI and your S32&#39;s firmware speak different editor protocols. Do what the error&#39;s `next:` line says. If the error names the older side, a retry or another cable does not help.</span></span>\n<span class="line"><span>- 4: the S32 said no, or the target is not in its list. Read the error. Do not retry.</span></span>\n<span class="line"><span>  If the error says the S32 changed during the read, tell the user and run the command again when they are done. An add that says it was saved is saved: do not add it again.</span></span>\n<span class="line"><span>- 5: a command that asks first ran without `--yes`, or the answer was no. Nothing changed.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## What only the panel does</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>- Firmware update, formatting, compacting or migrating storage.</span></span>\n<span class="line"><span>- Pressing panel buttons and text entry.</span></span>\n<span class="line"><span>- Turning ARRANGE on: the CLI writes the song, the panel starts the playhead.</span></span>\n<span class="line"><span>- The CLI and the web editor never run at the same time.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## Reference</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>- https://s32-manual.shik.tech/llms.txt: an index of the AI and s32 CLI pages. Every page it links, except the manual home, is a Markdown copy.</span></span>\n<span class="line"><span>- https://s32-manual.shik.tech/ai/prompts: prompts with checked commands and read-backs.</span></span>\n<span class="line"><span>- `s32 &lt;command&gt; --help` and `s32 commands --json`: every command with its keys and values.</span></span></code></pre></div><p>To install the s32 CLI yourself, see <a href="./../developers/getting-started#manual-install">Manual install</a>.</p><h2 id="rehearse-without-the-s32" tabindex="-1">Rehearse without the S32 <a class="header-anchor" href="#rehearse-without-the-s32" aria-label="Permalink to &quot;Rehearse without the S32&quot;">​</a></h2><p>To rehearse without hardware, have the agent work against the simulator. The simulator starts fresh on every run. Its ids, names and ranges are not your S32&#39;s.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repl</span></span></code></pre></div>',11)),r(e,null,{default:h(()=>[...a[0]||(a[0]=[s("ul",null,[s("li",null,[s("a",{href:"./"},"Overview"),n(" — What an agent can do with your S32, in three steps")]),s("li",null,[s("a",{href:"./prompts"},"Prompts and examples"),n(" — Quick starters and prompts for racks, modulation and knob mappings, with checked commands")]),s("li",null,[s("a",{href:"./safe-changes"},"Change safely"),n(" — Read, preview, ask, change, check")]),s("li",null,[s("a",{href:"./for-agents"},"For agents"),n(" — What agents read: llms.txt, Markdown copies, finding commands")])],-1)])]),_:1})])}const v=t(c,[["render",d]]);export{w as __pageData,v as default};
